module IIR_Filter(
    input clk,
    input reset,
    input signed [7:0] x,
    output reg signed [7:0] y
);
    reg signed [7:0] x1, x2; // previous inputs
    reg signed [7:0] y1, y2; // previous outputs

    // Coefficients
    parameter signed [7:0] b0 = 8'h01;
    parameter signed [7:0] b1 = 8'hFF; // -1
    parameter signed [7:0] b2 = 8'h04; // 0.5 * 16 = 4
    parameter signed [7:0] a1 = 8'hFC; // -0.5 * 16 = -4
    parameter signed [7:0] a2 = 8'hBF; // 0.75 * 16 = 12

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            y <= 0;
            x1 <= 0;
            x2 <= 0;
            y1 <= 0;
            y2 <= 0;
        end else begin
            // Shift previous values
            x2 <= x1;
            x1 <= x;
            y2 <= y1;
            y1 <= y;

            // IIR filter formula
            y <= (b0 * x) + (b1 * x1) + (b2 * x2) + (a1 * y1) + (a2 * y2);
        end
    end
endmodule

