module PID_Controller (  
    input wire clk,  
    input wire rst,  
    input wire signed [15:0] setpoint,  
    input wire signed [15:0] process_variable,  
    output reg signed [15:0] control_output  
);  
    reg signed [15:0] error;  
    reg signed [15:0] prev_error;  
    reg signed [15:0] integral;  
    parameter signed [15:0] Kp = 16'd2; // Proportional gain  
    parameter signed [15:0] Ki = 16'd1; // Integral gain  
    parameter signed [15:0] Kd = 16'd1; // Derivative gain  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            control_output <= 16'd0;  
            integral <= 16'd0;  
            prev_error <= 16'd0;  
        end else begin  
            error <= setpoint - process_variable;  
            integral <= integral + error;  
            control_output <= (Kp * error) + (Ki * integral) + (Kd * (error - prev_error));  
            prev_error <= error;  
        end  
    end  
endmodule

