module uart_transmitter(  
    input wire clk,          // System clock  
    input wire rst,          // Reset signal  
    input wire start,        // Start transmission signal  
    input wire [7:0] data,   // 8-bit data input  
    output reg tx,           // Serial transmission output  
    output reg busy          // Busy flag indicating transmission in progress  
);  
    reg [3:0] bit_count;     // Bit counter  
    reg [9:0] shift_reg;     // Shift register for 10 bits (1 start + 8 data + 1 stop)  
    localparam IDLE = 2'b00,  
               START = 2'b01,  
               DATA = 2'b10,  
               STOP = 2'b11;  
    reg [1:0] state, next_state;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            busy <= 0;  
            bit_count <= 0;  
            tx <= 1;  
        end else begin  
            state <= next_state;  
        end  
    end  

    always @(*) begin  
        next_state = state;  
        case (state)  
            IDLE: begin  
                if (start) begin  
                    shift_reg <= {1'b1, data, 1'b0}; // Prepare for transmission  
                    next_state = START;  
                    busy = 1;  
                    bit_count = 0;  
                end  
            end  
            START: begin  
                tx = 0; // Start bit  
                next_state = DATA;  
            end  
            DATA: begin  
                if (bit_count < 8) begin  
                    tx = shift_reg[bit_count];  
                    bit_count = bit_count + 1;  
                end else begin  
                    next_state = STOP;  
                end  
            end  
            STOP: begin  
                tx = 1; // Stop bit  
                busy = 0;  
                next_state = IDLE;  
            end  
        endcase  
    end  
endmodule

