module deserializer_32bit(  
    input wire clk,  
    input wire reset,  
    input wire [31:0] data_in,  
    input wire valid_in,  
    output reg [7:0] data_out,  
    output reg valid_out  
);  
    reg [1:0] byte_count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            byte_count <= 2'b00;  
            data_out <= 8'b0;  
            valid_out <= 1'b0;  
        end else if (valid_in) begin  
            data_out <= data_in[byte_count*8 +: 8];  
            valid_out <= 1'b1;  
            byte_count <= byte_count + 1;  
        end else begin  
            valid_out <= 1'b0;  
        end  
    end  
endmodule

