            8'h02: pixel_out = 8'h20;
            8'h03: pixel_out = 8'h30;
            8'h04: pixel_out = 8'h40;
            // ... complete mapping for all 256 values ...
            8'hFF: pixel_out = 8'hFF;
            default: pixel_out = pixel_in; // Default case
        endcase
    end
