module PIPO_Shift_Register #(parameter N = 8) (  
    input wire clk,  
    input wire reset,  
    input wire load,  
    input wire [N-1:0] data_in,  
    output reg [N-1:0] data_out,  
    output reg serial_out  
);  
    reg [N-1:0] register;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            register <= 0;  
            data_out <= 0;  
            serial_out <= 0;  
        end else if (load) begin  
            register <= data_in;  
        end else begin  
            data_out <= register;  
            serial_out <= register[0];  
            register <= {1'b0, register[N-1:1]};  
        end  
    end  
endmodule

